fn solve(n: i8) -> i8 {
    // If n is odd, no rectangle with integer sides can have this perimeter
    if n % 2 != 0 {
        return 0;
    }
    
    let half_n = n / 2;
    
    // Count unordered pairs (a, b) with a < b and a + b = half_n
    // The number of such pairs is floor((half_n - 1) / 2)
    let mut count = (half_n - 1) / 2;
    
    // If n is divisible by 4, we need to subtract 1 to exclude the square case
    if n % 4 == 0 {
        count -= 1;
    }
    
    count
}